sys_script_include.script:
var CiscoSecureAccessGetWebhookUrl = Class.create();
CiscoSecureAccessGetWebhookUrl.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // Simple test message
    getMessage: function () {
        return "Server says hello!";
    },

    // Fetch API Info
    getApiInfo: function () {
        var apiName = this.getParameter('sysparm_api_name') || "Cisco Secure Access Event Management";
        var resourceName = "Post Event For Secure Event Management";

        var result = {};

        // Find API
        var apiGR = new GlideRecord("sys_ws_definition");
        apiGR.addQuery("name", apiName);
        apiGR.query();
        if (!apiGR.next()) {
            result.error = "API not found: " + apiName;
            return JSON.stringify(result);
        }

        // Find Resource
        var resGR = new GlideRecord("sys_ws_operation");
        resGR.addQuery("web_service_definition", apiGR.sys_id);
        resGR.addQuery("name", resourceName);
        resGR.query();
        if (!resGR.next()) {
            result.error = "Resource not found: " + resourceName;
            return JSON.stringify(result);
        }

        // Build full URL
        var instanceUrl = gs.getProperty("glide.servlet.uri") || "";
        if (instanceUrl.endsWith("/")) {
            instanceUrl = instanceUrl.slice(0, -1); // remove trailing slash
        }

        var basePath = apiGR.getValue("base_uri") || "";
        var resPath = resGR.getValue("relative_path") || "";

        // Normalize slashes for basePath
        if (!basePath.startsWith("/")) {
            basePath = "/" + basePath;
        }
        if (basePath.endsWith("/")) {
            basePath = basePath.slice(0, -1);
        }

        // Normalize slashes for resPath
        if (!resPath.startsWith("/")) {
            resPath = "/" + resPath;
        }

        var fullUrl = instanceUrl + basePath + resPath;

        // Return JSON
        result = {
            name: apiGR.getValue("name"),
            api_id: apiGR.getValue("service_id"),
            base_path: basePath,
            full_url: fullUrl,
            active: apiGR.getValue("active"),
            is_versioned: apiGR.getValue("versioned")
        };

        return JSON.stringify(result);
    },

    type: 'CiscoSecureAccessGetWebhookUrl'
});
